// Turns the comma-separated hashtag list into one item per hashtag
const cfg = $input.first().json;
return cfg.hashtags
  .split(',')
  .map(h => h.trim().replace(/^#/, '').toLowerCase())
  .filter(Boolean)
  .map(hashtag => ({ json: { ...cfg, hashtag } }));

// Flattens top_media results, tags each post with its hashtag,
// removes duplicates and keeps the best N posts per hashtag.
const out = [];
const seen = new Set();
const items = $input.all();

for (let i = 0; i < items.length; i++) {
  const src = $('Split Hashtag List').itemMatching(i).json;
  const posts = (items[i].json.data || [])
    .sort((a, b) => ((b.like_count || 0) + (b.comments_count || 0)) - ((a.like_count || 0) + (a.comments_count || 0)))
    .slice(0, src.postsPerHashtag);

  for (const p of posts) {
    if (seen.has(p.id)) continue;
    seen.add(p.id);
    out.push({ json: {
      hashtag: '#' + src.hashtag,
      postId: p.id,
      permalink: p.permalink,
      mediaType: p.media_type,
      caption: (p.caption || '').slice(0, 1500),
      likes: p.like_count ?? null,
      comments: p.comments_count ?? null,
      postedAt: p.timestamp,
      brandVoice: src.brandVoice,
      myNiche: src.myNiche,
    }});
  }
}
return out;

