// Merges the AI analysis back onto each post for the digest sheet
return $input.all().map((item, i) => {
  const post = $('Flatten and Tag Posts').itemMatching(i).json;
  const ai = item.json.output || {};
  return { json: {
    'Date Found': $now.toFormat('yyyy-MM-dd'),
    'Hashtag': post.hashtag,
    'Post Link': post.permalink,
    'Media Type': post.mediaType,
    'Likes': post.likes,
    'Comments': post.comments,
    'Relevance Score': ai.relevanceScore ?? 0,
    'Post Summary': ai.summary || '',
    'Why Engage': ai.whyEngage || '',
    'Comment Option 1': (ai.commentOptions || [])[0] || '',
    'Comment Option 2': (ai.commentOptions || [])[1] || '',
    'Comment Option 3': (ai.commentOptions || [])[2] || '',
    'Status': 'To Review',
    'Post ID': post.postId,
  }};
});
